const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const wdpa = ee.FeatureCollection('WCMC/WDPA/current/polygons');
    const aoiCandidates = wdpa.filter(ee.Filter.or(
      ee.Filter.stringContains('NAME', 'Isles Dern'),
      ee.Filter.stringContains('ORIG_NAME', 'Isles Dern'),
      ee.Filter.stringContains('NAME', 'Dernières'),
      ee.Filter.stringContains('NAME', 'Dernieres')
    ));
    const aoiSize = await aoiCandidates.size().getInfo();
    if (!aoiSize || aoiSize === 0) {
      console.log('WDPA matches: 0');
      console.log('C1');
      return;
    }
    const aoi = aoiCandidates.union(1).geometry();
    const aoiArea_m2 = await aoi.area(1).getInfo();
    console.log(`WDPA matches: ${aoiSize}, AOI km²: ${(aoiArea_m2/1e6).toFixed(2)}`);

    const baseStart = '1999-01-01', baseEnd = '2001-12-31';
    const recentStart = '2023-01-01', recentEnd = '2024-12-31';

    // 2. Helpers: Masking & MNDWI
    function maskScaleL57(img) {
      const qa = img.select('QA_PIXEL');
      const mask = qa.bitwiseAnd(1 << 3).eq(0) // Cloud
        .and(qa.bitwiseAnd(1 << 4).eq(0))      // Cloud shadow
        .and(qa.bitwiseAnd(1 << 1).eq(0))      // Dilated cloud
        .and(qa.bitwiseAnd(1 << 2).eq(0));     // Cirrus
      const optical = img.select(['SR_B1','SR_B2','SR_B3','SR_B4','SR_B5','SR_B7'])
        .multiply(0.0000275).add(-0.2).clamp(0,1);
      return img.addBands(optical, null, true).updateMask(mask);
    }
    function maskScaleL89(img) {
      const qa = img.select('QA_PIXEL');
      const mask = qa.bitwiseAnd(1 << 3).eq(0) // Cloud
        .and(qa.bitwiseAnd(1 << 4).eq(0))      // Cloud shadow
        .and(qa.bitwiseAnd(1 << 1).eq(0))      // Dilated cloud
        .and(qa.bitwiseAnd(1 << 2).eq(0));     // Cirrus
      const optical = img.select(['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7'])
        .multiply(0.0000275).add(-0.2).clamp(0,1);
      return img.addBands(optical, null, true).updateMask(mask);
    }
    function addMNDWI_L57(img) {
      const green = img.select('SR_B2');
      const swir1 = img.select('SR_B5');
      const m = green.subtract(swir1).divide(green.add(swir1)).rename('MNDWI');
      return m.updateMask(img.mask().reduce('min')); // preserve valid mask
    }
    function addMNDWI_L89(img) {
      const green = img.select('SR_B3');
      const swir1 = img.select('SR_B6');
      const m = green.subtract(swir1).divide(green.add(swir1)).rename('MNDWI');
      return m.updateMask(img.mask().reduce('min'));
    }
    function s2MaskAndMNDWI(img) {
      const scl = img.select('SCL');
      const valid = scl.eq(4).or(scl.eq(5)).or(scl.eq(6)).or(scl.eq(7)).or(scl.eq(11));
      const m = img.select('B3').subtract(img.select('B11'))
        .divide(img.select('B3').add(img.select('B11'))).rename('MNDWI');
      return m.updateMask(valid);
    }

    // 3. Data Acquisition & Check
    const l5_base = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterDate(baseStart, baseEnd).filterBounds(aoi)
      .map(maskScaleL57).map(addMNDWI_L57);
    const l7_base = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterDate(baseStart, baseEnd).filterBounds(aoi)
      .map(maskScaleL57).map(addMNDWI_L57);
    const baseCol = l5_base.merge(l7_base);
    let baseCount = await baseCol.size().getInfo();

    if (baseCount === 0) {
      // widen baseline window
      const l5b = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterDate('1998-01-01','2002-12-31').filterBounds(aoi)
        .map(maskScaleL57).map(addMNDWI_L57);
      const l7b = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterDate('1998-01-01','2002-12-31').filterBounds(aoi)
        .map(maskScaleL57).map(addMNDWI_L57);
      var baseCol2 = l5b.merge(l7b);
      baseCount = await baseCol2.size().getInfo();
    }

    const l8_recent = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(recentStart, recentEnd).filterBounds(aoi)
      .map(maskScaleL89).map(addMNDWI_L89);
    const l9_recent = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterDate(recentStart, recentEnd).filterBounds(aoi)
      .map(maskScaleL89).map(addMNDWI_L89);
    let recentCol = l8_recent.merge(l9_recent);
    let recentCount = await recentCol.size().getInfo();

    // Fall back to Sentinel-2 if needed for recent
    let usedS2Recent = false;
    if (recentCount === 0) {
      const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterDate('2022-01-01','2024-12-31').filterBounds(aoi)
        .map(function(img){ return img.updateMask(img.select('QA60').bitwiseAnd(1<<10).eq(0)
          .and(img.select('QA60').bitwiseAnd(1<<11).eq(0))); }) // extra mask
        .map(s2MaskAndMNDWI);
      recentCol = s2;
      recentCount = await recentCol.size().getInfo();
      usedS2Recent = true;
    }

    // If still no data
    if (baseCount === 0 || recentCount === 0) {
      console.log(`Baseline Images: ${baseCount}, Recent Images: ${recentCount}`);
      console.log('C1');
      return;
    }

    console.log(`Baseline Images: ${baseCount}`);
    console.log(`Recent Images: ${recentCount}${usedS2Recent ? ' (S2)' : ''}`);

    // 4. Composites and Land/Water classification
    const mndwiBase = baseCount > 0 ? baseCol.median().rename('MNDWI') : null;
    const mndwiRecent = recentCount > 0 ? recentCol.median().rename('MNDWI') : null;

    if (mndwiBase === null || mndwiRecent === null) {
      console.log('C1');
      return;
    }

    const waterBase = mndwiBase.gt(0);
    const landBase = waterBase.not().rename('land');
    const waterRecent = mndwiRecent.gt(0);
    const landRecent = waterRecent.not().rename('land');

    // 5. Validation: Pixel counts & Areas
    const scale = 30;
    const v0Dict = await mndwiBase.reduceRegion({
      reducer: ee.Reducer.count(), geometry: aoi, scale: scale, maxPixels: 1e9
    }).getInfo();
    const v1Dict = await mndwiRecent.reduceRegion({
      reducer: ee.Reducer.count(), geometry: aoi, scale: scale, maxPixels: 1e9
    }).getInfo();

    const v0 = v0Dict ? (v0Dict.MNDWI || 0) : 0;
    const v1 = v1Dict ? (v1Dict.MNDWI || 0) : 0;
    if (v0 === 0 || v1 === 0) {
      console.log(`Valid pixels 2000-era: ${v0}, 2024-era: ${v1}`);
      console.log('C2');
      return;
    }

    const landPix0Dict = await landBase.reduceRegion({
      reducer: ee.Reducer.sum(), geometry: aoi, scale: scale, maxPixels: 1e9
    }).getInfo();
    const landPix1Dict = await landRecent.reduceRegion({
      reducer: ee.Reducer.sum(), geometry: aoi, scale: scale, maxPixels: 1e9
    }).getInfo();
    const landPix0 = landPix0Dict ? (landPix0Dict.land || 0) : 0;
    const landPix1 = landPix1Dict ? (landPix1Dict.land || 0) : 0;

    const area0_m2 = await ee.Image.pixelArea().updateMask(landBase).reduceRegion({
      reducer: ee.Reducer.sum(), geometry: aoi, scale: scale, maxPixels: 1e9
    }).get('area').getInfo();
    const area1_m2 = await ee.Image.pixelArea().updateMask(landRecent).reduceRegion({
      reducer: ee.Reducer.sum(), geometry: aoi, scale: scale, maxPixels: 1e9
    }).get('area').getInfo();

    if (area0_m2 === null || area1_m2 === null || area0_m2 <= 0) {
      console.log(`Areas invalid. A0: ${area0_m2}, A1: ${area1_m2}`);
      console.log('C3');
      return;
    }

    const a0_km2 = area0_m2 / 1e6;
    const a1_km2 = area1_m2 / 1e6;
    const loss_km2 = a0_km2 - a1_km2;
    const loss_pct = loss_km2 / a0_km2;

    // Print concise evidence (<=20 lines total)
    const totPixApprox = Math.max(1, Math.round(aoiArea_m2 / (scale*scale)));
    const cov0 = Math.min(100, (v0 / totPixApprox) * 100);
    const cov1 = Math.min(100, (v1 / totPixApprox) * 100);
    console.log(`Coverage 2000-era: ${cov0.toFixed(1)}% (valid px: ${v0}), Land px: ${Math.round(landPix0)}`);
    console.log(`Coverage 2024-era: ${cov1.toFixed(1)}% (valid px: ${v1}), Land px: ${Math.round(landPix1)}`);
    console.log(`Land 2000-era km²: ${a0_km2.toFixed(2)}`);
    console.log(`Land 2024-era km²: ${a1_km2.toFixed(2)}`);
    console.log(`Loss km²: ${loss_km2.toFixed(2)}, Loss %: ${(loss_pct*100).toFixed(1)}%`);

    // 6. Final Answer
    if (!isFinite(loss_pct)) {
      console.log('C3');
    } else if (loss_pct > 0.5) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
